function deepDiveStaleness(root) {
  const dir = path.join(root, REFS_DIR, "deep-dives");
  const stale = [];
  if (!fs.existsSync(dir)) return stale;
  for (const f of fs.readdirSync(dir).filter((f) => f.endsWith(".md"))) {
